import{DoubleTap,Camera,ARENA_WIDTH}from'./movement.mjs?v=alpha1';
import{ArenaMusic}from'./music.mjs';
import{Fight}from'./fight-core.mjs';
const $=id=>document.getElementById(id),canvas=$('fight'),c=canvas.getContext('2d'),game=new Fight(),doubleTap=new DoubleTap(),camera=new Camera(),scenery=new Image(),images={},keys={},names=['DEMONE','NINJA'];const net=window.__eclipseNet=window.__eclipseNet||{role:null,remoteInput:{move:0,block:false},input:null,onFrame:null,onEvents:null,applySnapshot:null};scenery.src='assets/eclipse-temple.png';
let loaded=false,chosen=0,last=0,particles=[],shake=0,toastT=0,audioEnabled=false,audioContext=null,flash=[0,0];const music=new ArenaMusic();const statusText='60 secondi · Primo a 2 round · P per mettere in pausa';
function tone(freq,duration=.08,type='sine',gain=.07){if(!audioEnabled)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();const osc=audioContext.createOscillator(),amp=audioContext.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,audioContext.currentTime);osc.frequency.exponentialRampToValueAtTime(Math.max(30,freq*.35),audioContext.currentTime+duration);amp.gain.setValueAtTime(gain,audioContext.currentTime);amp.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+duration);osc.connect(amp);amp.connect(audioContext.destination);osc.start();osc.stop(audioContext.currentTime+duration)}catch{}}
function clearKeys(){doubleTap.reset();Object.keys(keys).forEach(k=>keys[k]=false);syncPads()}
function syncPads(){document.querySelectorAll('[data-key]').forEach(b=>{const held=!!keys[b.dataset.key];b.classList.toggle('held',held);b.setAttribute('aria-pressed',String(held));const cpu=b.dataset.player==='1'&&game.mode==='cpu';b.disabled=cpu;b.closest('.command-card').classList.toggle('cpu',cpu)});$('padHint1').textContent=game.mode==='cpu'?'Controllato dalla CPU':'Tastiera · mouse · touch'}
function toast(text){$('toast').textContent=text;toastT=1.2}
function start(){if(!loaded)return;startMusic();clearKeys();game.events=[];game.start({mode:$('mode').value,character:chosen,difficulty:$('difficulty').value});camera.reset(game.fighters);$('menu').classList.add('hidden');$('result').classList.add('hidden');$('pauseScreen').classList.add('hidden');$('pause').disabled=false;$('pause').textContent='Pausa · P';$('status').textContent=statusText;particles=[];syncPads();canvas.focus();tone(270,.18)}
function menu(){clearKeys();game.phase='menu';game.paused=false;music.pause();musicLabel();$('menu').classList.remove('hidden');$('result').classList.add('hidden');$('pauseScreen').classList.add('hidden');$('pause').disabled=true;$('callout').textContent='';$('toast').textContent='';$('status').textContent='Scegli il lottatore e la modalità per iniziare.'}
function pause(){if(!['countdown','fight','roundOver'].includes(game.phase))return;game.paused=!game.paused;clearKeys();$('pauseScreen').classList.toggle('hidden',!game.paused);$('pause').textContent=game.paused?'Riprendi · P':'Pausa · P';if(!game.paused){canvas.focus();startMusic()}else{music.pause();musicLabel()}}
$('start').onclick=start;$('rematch').onclick=start;$('resultMenu').onclick=menu;$('pauseMenu').onclick=menu;$('pause').onclick=pause;$('resume').onclick=pause;$('mode').onchange=()=>{$('difficulty').disabled=$('mode').value==='local'};
document.querySelectorAll('[data-character]').forEach(b=>b.onclick=()=>{chosen=Number(b.dataset.character);document.querySelectorAll('[data-character]').forEach(el=>{let selected=Number(el.dataset.character)===chosen;el.classList.toggle('selected',selected);el.setAttribute('aria-pressed',String(selected))});if(game.phase==='menu'){game.fighters[0].char=chosen;game.fighters[1].char=1-chosen}tone(440,.06)});
$('sound').onclick=()=>{audioEnabled=!audioEnabled;$('sound').textContent=audioEnabled?'Effetti: accesi':'Effetti: spenti';$('sound').setAttribute('aria-pressed',String(audioEnabled));tone(500,.08)};$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('arena').requestFullscreen()}catch{toast('Schermo intero non disponibile in questo browser')}};
const mapping={u:[0,'punch'],i:[0,'kick'],q:[0,'dodge'],w:[0,'jump'],s:[0,'block'],j:[1,'punch'],k:[1,'kick'],l:[1,'dodge'],arrowup:[1,'jump'],arrowdown:[1,'block']};
function down(k){const directions={a:[0,-1],d:[0,1],arrowleft:[1,-1],arrowright:[1,1]};if(!keys[k]&&directions[k]&&game.phase==='fight'&&!game.paused){const[id,dir]=directions[k];if((id===0||game.mode==='local')&&doubleTap.press(id,dir,performance.now()))game.dash(id,dir)}if(!keys[k]&&mapping[k]){let[id,type]=mapping[k];if(id===0||game.mode==='local')game.action(id,type)}keys[k]=true;syncPads()}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['INPUT','SELECT'].includes(e.target.tagName))return;if(k==='p'||k==='escape'){e.preventDefault();if(!e.repeat)pause();return}if(mapping[k]||['a','d','arrowleft','arrowright'].includes(k)){if(game.phase!=='menu')e.preventDefault();down(k)}});window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;syncPads()});window.addEventListener('blur',()=>{clearKeys();if(['countdown','fight'].includes(game.phase)&&!game.paused)pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearKeys();if(['countdown','fight'].includes(game.phase)&&!game.paused)pause()}});
document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);down(b.dataset.key)};b.addEventListener('click',e=>{if(e.detail===0){down(b.dataset.key);keys[b.dataset.key]=false;syncPads()}});for(const evt of['pointerup','pointercancel','lostpointercapture'])b.addEventListener(evt,()=>{keys[b.dataset.key]=false;syncPads()})});
function events(){for(const event of game.events){if(event.type==='dash'){tone(130,.12,'triangle',.03);toast('SCATTO')}if(event.type==='round')camera.reset(game.fighters);if(event.type==='swing')tone(180,.08,'triangle',.025);if(event.type==='hit'||event.type==='block'){const blocked=event.type==='block';shake=blocked?3:8;flash[event.id]=.14;tone(blocked?650:100,blocked?.05:.13,blocked?'triangle':'sawtooth',.06);for(let n=0;n<13;n++)particles.push({x:event.x,y:event.y,vx:(Math.random()-.5)*330,vy:(Math.random()-.5)*280,life:.28,color:blocked?'#d5e9df':'#f6b56d'});if(blocked)toast('PARATA · −2');else if(event.combo>=2)toast(event.combo+' COLPI · '+names[game.fighters[event.attacker].char]);else toast('COLPO A SEGNO · −'+event.damage)}if(event.type==='evade')toast('SCHIVATA RIUSCITA');if(event.type==='empty')toast('ENERGIA INSUFFICIENTE');if(event.type==='fight')tone(440,.22,'triangle');if(event.type==='roundEnd'){clearKeys();tone(event.winner===null?180:360,.4,'triangle');if(event.match){const winner=game.fighters[event.winner];$('winnerTitle').textContent=names[winner.char]+' VINCE';$('score').textContent=game.wins[0]+' — '+game.wins[1]+(game.mode==='cpu'?(event.winner===0?' · Hai conquistato l’arena.':' · La rivincita ti aspetta.'):' · Scontro concluso.');$('result').classList.remove('hidden');$('pause').disabled=true;$('status').textContent='Scontro concluso · Scegli Rivincita per giocare ancora.'}}}game.events=[]}
function background(t){const g=c.createLinearGradient(0,0,0,650);g.addColorStop(0,'#302239');g.addColorStop(1,'#c7a07b');c.fillStyle=g;c.fillRect(0,0,1200,650);if(scenery.complete&&scenery.naturalWidth){c.drawImage(scenery,-camera.left*camera.zoom,0,ARENA_WIDTH*camera.zoom,650)}const top=c.createLinearGradient(0,0,0,155);top.addColorStop(0,'#100c1ce0');top.addColorStop(1,'#100c1c00');c.fillStyle=top;c.fillRect(0,0,1200,155);for(let i=0;i<25;i++){const worldX=(i*137+t*24)%ARENA_WIDTH;const x=(worldX-camera.left)*camera.zoom;const y=140+((i*83+t*16)%440);c.save();c.translate(x,y);c.rotate(t*.5+i);c.fillStyle=i%2?'#f5a7b77a':'#ffd39266';c.beginPath();c.ellipse(0,0,3.5,1.6,0,0,Math.PI*2);c.fill();c.restore()}}
function imageFor(f){if(f.action==='dash')return images.study[f.char][1];if(f.action==='kick'){const n=f.frame;return n===2||n===3?images.study[f.char][4]:n===1||n===4?images.study[f.char][0]:images.punch[f.char][0]}if(f.action==='idle')return f.walk>0&&Math.floor(f.walk*7)%2?images.study[f.char][1]:images.punch[f.char][0];return images[f.action][f.char][f.frame]}
function drawFighter(f){let image=imageFor(f),punch=image.src.includes('/punch/'),w=punch?270:324,h=punch?405:459;let airborne=f.action==='jump'&&f.frame>=2&&f.frame<=3;c.save();c.fillStyle='#3c342b30';c.beginPath();c.ellipse(f.x,594,airborne?35:58,airborne?5:9,0,0,Math.PI*2);c.fill();c.translate(f.x,592);c.scale(f.dir,1);if(f.action==='dash'){c.rotate(f.dashDir*f.dir*.055);c.globalAlpha*=.95}if(f.stun>0)c.rotate(-.025);if(flash[f.id]>0){c.shadowColor='#ffc88a';c.shadowBlur=18}c.drawImage(image,-w/2,-h,w,h);c.restore()}
function hud(){if(!game.fighters.length)return;game.fighters.forEach((f,i)=>{$('name'+i).textContent=names[f.char];$('role'+i).textContent=i===0?'GIOCATORE 1':game.mode==='cpu'?'CPU':'GIOCATORE 2';$('life'+i).style.width=f.hp+'%';$('energy'+i).style.width=f.energy+'%';$('dots'+i).textContent=[0,1].map(n=>game.wins[i]>n?'●':'○').join(' ')});$('round').textContent='ROUND '+Math.max(1,game.round);$('timer').textContent=Math.ceil(game.timer).toString().padStart(2,'0');let text='';if(game.phase==='countdown')text=game.phaseT<1?'ROUND '+game.round:game.phaseT<1.7?'PRONTI?':'COMBATTI!';else if(game.phase==='fight'&&game.phaseT<.5)text='COMBATTI!';else if(game.phase==='roundOver')text=game.roundWinner===null?'PAREGGIO':names[game.fighters[game.roundWinner].char]+' VINCE IL ROUND';$('callout').textContent=text}
function render(t){c.clearRect(0,0,1200,650);c.save();if(shake>0)c.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);background(t);c.save();c.translate(600,592);c.scale(camera.zoom,camera.zoom);c.translate(-camera.x,-592);if(loaded){for(const f of game.fighters){if(f.action==='dash'){for(let i=3;i>0;i--){c.save();c.globalAlpha=.12/i;const ghost={...f,x:f.x-f.dashDir*i*32};drawFighter(ghost);c.restore()}}drawFighter(f)}}particles.forEach(p=>{c.globalAlpha=p.life/.28;c.fillStyle=p.color;c.fillRect(p.x,p.y,4,4)});c.globalAlpha=1;c.restore();c.restore();hud()}
let loadCount=0;const tasks=[];for(const type of['punch','dodge','jump','block','study']){images[type]=[[],[]];for(let row=0;row<2;row++)for(let frame=0;frame<6;frame++)tasks.push(new Promise((resolve,reject)=>{const im=new Image;im.onload=()=>{images[type][row][frame]=im;loadCount++;$('start').textContent='CARICAMENTO '+Math.round(loadCount/60*100)+'%';resolve()};im.onerror=()=>reject(new Error(type+' '+row+' '+frame));im.src=`assets-alpha/${type}/${row}-${frame}.png`}))}
tasks.push(new Promise((resolve,reject)=>{if(scenery.complete&&scenery.naturalWidth)resolve();else{scenery.onload=resolve;scenery.onerror=()=>reject(new Error('Sfondo non caricato'))}}));
Promise.all(tasks).then(()=>{loaded=true;$('start').disabled=false;$('start').textContent='ENTRA NELL’ARENA →';game.start({character:chosen});game.phase='menu';game.events=[];camera.reset(game.fighters);syncPads()}).catch(()=>{$('start').textContent='CARICAMENTO FALLITO — RICARICA';$('status').textContent='Alcuni fotogrammi non sono stati caricati. Ricarica la pagina per riprovare.'});
function loop(ms){const dt=Math.min((ms-last)/1000,.2);last=ms;const localInput=[{move:Number(!!keys.d)-Number(!!keys.a),block:!!keys.s},{move:Number(!!keys.arrowright)-Number(!!keys.arrowleft),block:!!keys.arrowdown}];const input=net.role==='host'?[localInput[0],net.remoteInput]:net.role==='guest'?[{move:0,block:false},localInput[1]]:localInput;net.input=input;let remaining=dt;while(remaining>0){const slice=Math.min(remaining,1/60);if(net.role!=='guest')game.update(slice,input);remaining-=slice;}events();if(net.onFrame)net.onFrame(game);if(game.fighters.length&&!game.paused)camera.update(game.fighters,dt);if(!game.paused){shake*=.8;flash=flash.map(v=>Math.max(0,v-dt));particles.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt});particles=particles.filter(p=>p.life>0);toastT-=dt;if(toastT<=0)$('toast').textContent=''}render(ms/1000);requestAnimationFrame(loop)}requestAnimationFrame(loop);

function musicLabel(){$('music').textContent=music.enabled?(music.playing?'♫ Musica: accesa':'♫ Musica: pronta'):'♫ Musica: spenta';$('music').setAttribute('aria-pressed',String(music.enabled))}
async function startMusic(){try{await music.play();musicLabel()}catch{music.disable();$('music').textContent='Musica non disponibile';$('music').setAttribute('aria-pressed','false');toast('Il browser non ha attivato l’audio. Prova il pulsante Musica.')}}
$('music').onclick=()=>{if(music.enabled){music.disable();musicLabel()}else{music.enabled=true;startMusic()}};
$('musicVolume').oninput=e=>{music.setVolume(Number(e.target.value)/100);$('volumeValue').textContent=e.target.value+'%'};
